function find_rules($css, $pattern) {
    echo "=== Searching for: $pattern ===\n";
    $offset = 0;
    while (($pos = strpos($css, $pattern, $offset)) !== false) {
        $start = max(0, $pos - 100);
        $end = min(strlen($css), $pos + 200);
        echo "... " . substr($css, $start, $end - $start) . " ...\n\n";
        $offset = $pos + strlen($pattern);
        if ($offset >= strlen($css)) break;
    }
}

